effect.shader:
const int N = 9;
const float OFF[9] = float[9](-4.0,-3.0,-2.0,-1.0,0.0,1.0,2.0,3.0,4.0);
const float WT[9]  = float[9](0.028,0.065,0.121,0.175,0.198,0.175,0.121,0.065,0.028);

float fora(vec2 uv) {
    vec2 p = uv - center; p.x *= acAspect;
    float r = length(p);
    return smoothstep(sharpArea, sharpArea + falloff, r);
}

void main() {
    vec4 original = texture(inputImg, acScreenNorm);
    float k = fora(acScreenNorm);
    float raio = radius * k;
    if (raio <= 0.0 && acPass == 1) { fragColor = original; return; }

    vec2 d = (acPass == 0) ? vec2(1.0, 0.0) : vec2(0.0, 1.0);
    vec2 passo = d * acTexelSize * (raio * acEscalaDePixel);
    vec4 soma = vec4(0.0);
    for (int i = 0; i < N; i++) {
        vec2 uv = acScreenNorm + passo * OFF[i];
        soma += ((acPass == 0) ? texture(inputImg, uv) : texture(hblur, uv)) * WT[i];
    }
    if (acPass == 0) { fragColor = soma; }
    else { fragColor = mix(original, soma, k); }
}
